/* American Sign Language Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Name signs": "In ASL, people are known by name signs: unique signs bestowed by the Deaf community, never self-assigned.", "Initialized name signs": "Many name signs use the handshape of the person's initial letter placed at a meaningful location.", "Descriptive name signs": "Some name signs describe a memorable trait, habit or story about the person.", "Fingerspelled names": "New acquaintances introduce themselves by fingerspelling; the sign name comes later, given by Deaf friends.", "Marlee Matlin's name sign": "The celebrated Deaf actress carries a community-given name sign used across the Deaf world.", "Nyle DiMarco's name sign": "The Deaf model and activist is known by his community-given name sign.", "Fingerspelled surnames": "Family names are fingerspelled letter by letter; there is no separate surname sign system.", "Gallaudet": "Gallaudet University, the Deaf university, has its own long-established name sign.", "Initialized family signs": "Some families share an initialized sign element across their name signs.", "Name-sign inheritance": "Children of Deaf adults often receive name signs echoing a parent's sign."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Name signs';
console.log(lookup(q));

